-- ── ② SCM_ADM_EXCEL_COLUMNS ──

BEGIN
  MERGE INTO SCM_MGR.SCM_ADM_EXCEL_COLUMNS T
  USING ( SELECT 'DMF0082' AS PROGRAM_ID, 'FcstNPrice' AS SHEET_NAME, 'PKG_DMF0082.P_DMF0082_EXCEL_UPLOAD' AS STORAGE_SQL_ID, 'Div|End Customer|Sales Site|Model|Incoterms|FCST Type|Customs Handbook|Cell Prod Site|Currency|Measure|M4|M5|M6|M7|M8|M9|M10|M11|M12|M13|M14|M15|M16' AS HEADER_CONTENT, 70 AS OPTION_ATTRIBUTE_COLUMN_NUMBER, 'Y' AS VALID_YN, 'kjiyoon_es' AS CREATED_BY, TO_DATE('2025-05-23 15:33:24','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-08-12 12:10:36','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE, NULL AS ATTRIBUTE1, NULL AS ATTRIBUTE2, NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, NULL AS ATTRIBUTE6, NULL AS ATTRIBUTE7, NULL AS ATTRIBUTE8, NULL AS ATTRIBUTE9, NULL AS ATTRIBUTE10, NULL AS XLS_COLUMN_CODE_MATCH FROM DUAL ) S
     ON ( T.PROGRAM_ID = S.PROGRAM_ID AND T.SHEET_NAME = S.SHEET_NAME )
   WHEN MATCHED THEN UPDATE SET T.STORAGE_SQL_ID = S.STORAGE_SQL_ID, T.HEADER_CONTENT = S.HEADER_CONTENT, T.OPTION_ATTRIBUTE_COLUMN_NUMBER = S.OPTION_ATTRIBUTE_COLUMN_NUMBER, T.VALID_YN = S.VALID_YN, T.ATTRIBUTE1 = S.ATTRIBUTE1, T.ATTRIBUTE2 = S.ATTRIBUTE2, T.ATTRIBUTE3 = S.ATTRIBUTE3, T.ATTRIBUTE4 = S.ATTRIBUTE4, T.ATTRIBUTE5 = S.ATTRIBUTE5, T.ATTRIBUTE6 = S.ATTRIBUTE6, T.ATTRIBUTE7 = S.ATTRIBUTE7, T.ATTRIBUTE8 = S.ATTRIBUTE8, T.ATTRIBUTE9 = S.ATTRIBUTE9, T.ATTRIBUTE10 = S.ATTRIBUTE10, T.XLS_COLUMN_CODE_MATCH = S.XLS_COLUMN_CODE_MATCH, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
   WHEN NOT MATCHED THEN INSERT (PROGRAM_ID, SHEET_NAME, STORAGE_SQL_ID, HEADER_CONTENT, OPTION_ATTRIBUTE_COLUMN_NUMBER, VALID_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, XLS_COLUMN_CODE_MATCH) VALUES (S.PROGRAM_ID, S.SHEET_NAME, S.STORAGE_SQL_ID, S.HEADER_CONTENT, S.OPTION_ATTRIBUTE_COLUMN_NUMBER, S.VALID_YN, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE, S.ATTRIBUTE1, S.ATTRIBUTE2, S.ATTRIBUTE3, S.ATTRIBUTE4, S.ATTRIBUTE5, S.ATTRIBUTE6, S.ATTRIBUTE7, S.ATTRIBUTE8, S.ATTRIBUTE9, S.ATTRIBUTE10, S.XLS_COLUMN_CODE_MATCH);
END;
/

